import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Bir görseli bulanıklaştırmak ya da pikselleştirmek dakikalar sürer. Program kurmazsınız, fotoğrafınız cihazınızdan ayrılmaz ve sonunda sansürlü bir kopya indirirsiniz.</p>\n<p>Bu yazı, işlemi altı adımda anlatıyor. İster tek bir yüz ister bütün bir belge gizleyin, adımlar aynıdır.</p>\n<p>Sonunda bulanıklaştırma ve pikselleştirme arasında nasıl seçim yapacağınızı, fırçayı nasıl kullanacağınızı ve hataları nasıl düzelteceğinizi öğreneceksiniz.</p>\n<h2 id=\"before-you-start\">Başlamadan önce: gizlenecekleri listeleyin</h2>\n<p>Önce fotoğrafta gizlenmesi gerekenleri listeleyin. Yüzler, plakalar, adresler, metinler ve kimlik numaraları.</p>\n<p>Orijinal fotoğrafın bir yedeğini alın. Sansür geri alınamaz; orijinal güvenlik ağınızdır.</p>\n<p>Yöntemi belirleyin: yüz için bulanıklaştırma, metin için pikselleştirme genellikle daha güvenlidir.</p>\n<h2 id=\"step-by-step\">Görsel bulanıklaştırma ve pikselleştirme altı adımda</h2>\n<p>Önce sansür aracını açıp fotoğrafı yükleyin. Önizlemede görselin tamamını inceleyin.</p>\n<p>Sonra yöntemi seçin ve fırçayla gizlenecek alanları boyayın. Gücü ayarlayın.</p>\n<p>Son olarak sonucu kontrol edip indirin. Önizlemeyi atlamayın; açık kalan nokta sansürü bozar.</p>\n<ol>\n<li>Bulanıklaştırma aracını açın ve fotoğrafınızı yükleyin.</li>\n<li>Bulanıklaştırma ya da pikselleştirme yöntemini seçin.</li>\n<li>Fırça boyutunu ayarlayın; yüz için büyük, plaka için küçük.</li>\n<li>Fırçayla gizlenecek alanların üzerini boyayın.</li>\n<li>Gücü ayarlayın ve sonucu önizlemede kontrol edin.</li>\n<li>Sansürlü görseli indirin.</li>\n</ol>\n<h2 id=\"choosing-blur-or-pixelate\">Bulanıklaştırma ve pikselleştirme arasında seçim</h2>\n<p>Yüzler için bulanıklaştırma doğal görünür. Yumuşak geçiş, fotoğrafı bozmaz.</p>\n<p>Metin ve plakalar için pikselleştirme daha güvenlidir. Bulanık metin bazen okunabilir.</p>\n<p>İkisini aynı görselde birleştirebilirsiniz. Yüzü bulanıklaştırın, plakayı pikselleştirin.</p>\n<h2 id=\"using-brush-mode\">Fırça alanı modunu kullanmak</h2>\n<p>Fırça modunda gizlenecek yeri kendiniz boyarsınız; yüzü kapatırsınız, fotoğrafın diğer kısımları olduğu gibi kalır.</p>\n<p>Fırça boyutunu gizlenecek alana göre ayarlayın; yüz için büyük, plaka için küçük fırça idealdir.</p>\n<p>Boyarken fırçayı kenarların üstünden de geçirin; açıkta kalan küçük bir nokta, gizlemeyi boşa çıkarır.</p>\n<h2 id=\"using-whole-image-mode\">Tam görsel modunu kullanmak</h2>\n<p>Fotoğrafın tamamını bulanıklaştırmak istiyorsanız tam görsel modunu seçin; bu mod, arka plan hazırlamak içindir.</p>\n<p>Portre arka planını yumuşatmak için bu modu seçin; konu keskin kalır, arka plan hoş bir bulanıklığa bürünür.</p>\n<p>Gizlilik için tam görsel modunu seçmeyin; fotoğrafın tamamını gizlemek, kareyi anlamsız hâle getirir.</p>\n<h2 id=\"setting-brush-size\">Fırça boyutunu ayarlamak</h2>\n<p>Fırçayı kapatacağınız ayrıntıdan bir parça büyük seçin; dar fırça, kenarları açıkta bırakır.</p>\n<p>Yüzü kapatırken fırçayı büyük tutun; plaka için küçük bir fırça işinizi görür.</p>\n<p>Fırça boyutunu boyarken ayarlayabilirsiniz. Farklı ayrıntılar, farklı boyut ister.</p>\n<h2 id=\"setting-strength\">Bulanıklık gücünü ve blok boyutunu ayarlamak</h2>\n<p>Bulanıklık gücü kaydırıcısıyla yumuşaklığı ayarlayın. Güvenlik için güçlü kullanın.</p>\n<p>Blok boyutu kaydırıcısıyla mozaik büyüklüğünü ayarlayın. Büyük bloklar daha güvenli gizler.</p>\n<p>Gücü test edin. Gizledikten sonra metni okumaya çalışın; okunmuyorsa yeterlidir.</p>\n<h2 id=\"fixing-mistakes\">Boyarken hataları düzeltmek</h2>\n<p>Yanlış yeri boyadıysanız geri alma düğmesini kullanın. Son işlem geri alınır.</p>\n<p>Atlanan noktayı fırçayla yeniden boyayın. Kenarların üzerinden geçtiğinizden emin olun.</p>\n<p>Her şeyi sıfırlamak isterseniz sıfırlama düğmesini kullanın. Fotoğraf orijinal hâline döner.</p>\n<h2 id=\"preview-and-compare\">İndirmeden önce önizlemeyi kontrol etmek</h2>\n<p>Her zaman önizlemeyi kontrol edin. Tüm gizlenecek alanların kapandığından emin olun.</p>\n<p>Karşılaştırma görünümüyle orijinali ve sansürlü sürümü yan yana inceleyin. Açık nokta var mı?</p>\n<p>Yakınlaştırarak kontrol edin. Küçük açık alanlar, tam boyutta belli olur.</p>\n<h2 id=\"choosing-export-format\">Dışa aktarma formatını seçmek</h2>\n<p>Fotoğrafları JPG biçiminde kaydedin. Küçük dosyalar paylaşımı kolaylaştırır.</p>\n<p>Saydamlık gerekiyorsa PNG seçin. JPG bu bilgiyi saklayamaz.</p>\n<p>Dışa aktarma kalitesini yüzde 85-90 seçin. Görünür kayıp olmadan dosya hafifler.</p>\n<h2 id=\"blurring-on-mobile\">Telefon ve tablette bulanıklaştırmak</h2>\n<p>Bulanıklaştırma aracını telefon tarayıcısında açın, fotoğrafı yükleyin ve fırçayla parmağınızla boyayın.</p>\n<p>Telefonda küçük ayrıntılar zordur. Hassas işler için bilgisayarı tercih edin.</p>\n<p>İndirilenler, telefonun İndirilenler klasöründe birikir. Bulamazsanız tarayıcının indirme geçmişine bakın.</p>\n<h2 id=\"blurring-screenshots\">Ekran görüntüsünü bulanıklaştırmak</h2>\n<p>Ekran görüntülerinde şifre ve kişisel bilgi gizlenmelidir. Fırçayla üzerlerini boyayın.</p>\n<p>Metin için pikselleştirme kullanın. Bulanık metin bazen okunabilir.</p>\n<p>Ekran görüntülerini PNG olarak kaydedin. Kayıpsız format, metni net tutar.</p>\n<h2 id=\"blurring-documents\">Belge fotoğrafını bulanıklaştırmak</h2>\n<p>Belge fotoğraflarında kimlik numarası ve adres gizlenmelidir. Fırçayla üzerlerini boyayın.</p>\n<p>Belgenin geri kalanı okunur kalmalıdır. Yalnızca hassas alanları gizleyin.</p>\n<p>Paylaşmadan önce sonucu kontrol edin. Hassas bilgi kalmadığından emin olun.</p>\n<h2 id=\"troubleshooting\">Yaygın sansür sorunlarını çözmek</h2>\n<p>Geri alma düğmesi yoksa sayfayı yenilemeyin. İşlem kaybolur; baştan başlayın.</p>\n<p>Fırça çalışmıyorsa fotoğrafın yüklendiğinden emin olun. Sayfayı yenileyip yeniden yükleyin.</p>\n<p>Sonuç bulanık görünüyorsa gücü azaltın. Aşırı güç, fotoğrafı bozar.</p>\n<h2 id=\"quick-tips\">Daha güvenli sansür için hızlı ipuçları</h2>\n<p>Güçlü gizleme kullanın. Hafif bulanıklık, yüzü tanınır bırakır.</p>\n<p>Kenarları kapatın. Açık kalan nokta, sansürü bozar.</p>\n<p>Paylaşmadan önce kontrol edin. Birkaç saniyelik kontrol, gizlilik hatasını önler.</p>\n<h2 id=\"blurring-for-presentations\">Sunum için fotoğraf bulanıklaştırmak</h2>\n<p>Sunumlarda arka planı bulanıklaştırın. Metin, düz zeminde okunur.</p>\n<p>Hafif bulanıklık kullanın. Doğal görünüm korunmalıdır.</p>\n<p>Sunumdan önce dosyaları test edin. Görsellerin açıldığından emin olun.</p>\n<p>Adım adım ilerleyin ve her fotoğrafı indirmeden önce kontrol edin. Karşılaştırma için <a href=\"/tr/blog/bulaniklastirma-vs-piksellestirme-gorsel\">bulanıklaştırma ve pikselleştirme karşılaştırmasına</a> bakın; kılavuzun tamamı <a href=\"/tr/blog/gorsel-bulaniklastir-piksellestir-rehberi\">bulanıklaştırma ve pikselleştirme kılavuzunda</a>. Konum verisi için <a href=\"/tr/gorsel-metadata-kaldir\">meta veri kaldırma</a> hazırdır; araç ise <a href=\"/tr/gorsel-bulaniklastir-piksellestir\">bulanıklaştırma ve pikselleştirme</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Grup fotoğrafında yalnızca bir yüzü nasıl bulanıklaştırırım?","answer":"Fırça modunu kullanın. Fırça boyutunu yüze göre ayarlayın ve yalnızca o yüzün üzerini boyayın; geri kalan net kalır. Yüzün tamamını gizleyin; yalnızca gözleri kapatmak yeterli değildir."},{"question":"Aynı görselin farklı bölümlerini hem bulanıklaştırıp hem pikselleştirebilir miyim?","answer":"Evet. Yüzü bulanıklaştırın, plakayı pikselleştirin; iki yöntem aynı görselde bir arada kullanılabilir. Her alan için uygun yöntemi seçin ve sonucu indirmeden önce kontrol edin."},{"question":"Plaka için hangi fırça boyutunu kullanmalıyım?","answer":"Küçük fırça yeterlidir; plaka dar bir alandır. Fırçanın plakadan biraz büyük olduğundan emin olun; kenarlar açık kalmamalıdır. Metin için pikselleştirme kullanın; bulanık metin bazen okunabilir."},{"question":"Telefonda ekran görüntüsünü nasıl bulanıklaştırırım?","answer":"Bulanıklaştırma aracını telefon tarayıcısında açın, ekran görüntüsünü yükleyin ve fırçayla hassas alanların üzerini boyayın. Metin için pikselleştirme kullanın. İndirilen dosya İndirilenler klasörüne gider."},{"question":"Geri alma ve sıfırlama düğmeleri neden yok?","answer":"Bazı araç sürümlerinde geri alma sınırlıdır; yanlış boyarsanız sayfayı yenilemeden önce dikkatli olun. Hata yaparsanız fırçayla üzerini yeniden boyayın ya da sıfırlama düğmesini kullanın. İş bitmeden indirmeyin."},{"question":"Çocuğumun bulanıklaştırılmış fotoğrafını çevrimiçi paylaşmak güvenli mi?","answer":"Güçlü bulanıklık ya da büyük bloklu pikselleştirme kullandıysanız evet. Hafif gizleme yeterli değildir; yüz tanınır kalabilir. Paylaşmadan önce sonucu kontrol edin ve konum verisini meta veri kaldırma aracıyla silin."}];
